import { Component } from '@angular/core';

@Component({
  selector: 'app-seleccionar-usuario',
  templateUrl: './seleccionar-usuario.component.html',
  styleUrls: ['./seleccionar-usuario.component.css']
})
export class SeleccionarUsuarioComponent {

}
<h1>Seccion de Usuarios</h1>

<a [routerLink]="['/login','jugador']">
  <button>Prueba Jugador Amateur</button>
</a>
<a [routerLink]="['/login','arrendador']">
  <button>Prueba Arrendador de Canchas</button>
</a>
